(function(){"use strict";if(window.OHMYZINE_OS_STAGE_HOST)return;var buttons=Array.prototype.slice.call(document.querySelectorAll(".js-article-toggle"));if(!buttons.length)return;function storageKey(button){return"oh-my-zine:"+button.dataset.articleAction+":"+button.dataset.articleId}function readState(button){try{return window.localStorage.getItem(storageKey(button))==="1"}catch(error){return button.getAttribute("aria-pressed")==="true"}}function writeState(button,isActive){try{window.localStorage.setItem(storageKey(button),isActive?"1":"0")}catch(error){}}function labelFor(button,isActive){if(button.dataset.articleAction==="save"){return isActive?"マイリストから削除":"マイリストに追加"}return isActive?"お気に入りから削除":"お気に入りに追加"}function sync(articleId,action,isActive){buttons.forEach(function(button){if(button.dataset.articleId!==articleId||button.dataset.articleAction!==action)return;button.classList.toggle("is-active",isActive);button.setAttribute("aria-pressed",String(isActive));button.setAttribute("aria-label",labelFor(button,isActive));button.textContent=isActive?button.dataset.onSymbol:button.dataset.offSymbol})}function announce(message){var oldToast=document.querySelector(".fashion-action-toast");if(oldToast)oldToast.remove();var toast=document.createElement("div");toast.className="fashion-action-toast";toast.setAttribute("role","status");toast.textContent=message;document.body.appendChild(toast);window.setTimeout(function(){toast.classList.add("is-visible")},20);window.setTimeout(function(){toast.classList.remove("is-visible");window.setTimeout(function(){toast.remove()},180)},1500)}buttons.forEach(function(button){sync(button.dataset.articleId,button.dataset.articleAction,readState(button));button.addEventListener("click",function(){var nextState=button.getAttribute("aria-pressed")!=="true";writeState(button,nextState);sync(button.dataset.articleId,button.dataset.articleAction,nextState);if(button.dataset.articleAction==="save"){announce(nextState?"マイリストに追加しました":"マイリストから削除しました")}else{announce(nextState?"お気に入りに追加しました":"お気に入りから削除しました")}})})})();